#!/bin/sh
# Pesque bootstrap installer: turns a fresh host into a working PDS.
#
#   curl -fsSL https://github.com/zeeetech/pesque/releases/latest/download/install.sh | sh
#
# This is a bootstrap, not a driver: it installs the host-side `pesque` CLI and
# one backend (docker or systemd), then prints the handoff steps: write a
# pesque.conf, `pesque up`, create the first account. There is no guided setup.
# TLS and the reverse proxy are the operator's responsibility; nothing is
# bundled. Secrets are generated by the release on first boot; this script
# writes nothing secret.
#
# Flags:
#   --backend docker|systemd              what to install (default: docker)
#   --hostname H                          domain clients will use
#   --mode single|multi   account mode
#   --tag T                               release tag (default: latest release)
#   --yes                                 non-interactive: flags or defaults only
#
# Overridable environment (mirrors, CI, tests):
#   PESQUE_REPO, PESQUE_BASE_URL, PESQUE_API_URL, PESQUE_TAG, PESQUE_PREFIX,
#   PESQUE_SYSROOT (test hook: prefix for the systemd /opt, /var and /etc paths)
set -eu

repo="${PESQUE_REPO:-zeeetech/pesque}"
base="${PESQUE_BASE_URL:-https://github.com/$repo/releases/download}"
api="${PESQUE_API_URL:-https://api.github.com/repos/$repo/releases/latest}"
sysroot="${PESQUE_SYSROOT:-}"
tag="${PESQUE_TAG:-}"

backend="docker"
hostname_val=""
mode=""
yes=0
answer=""

usage() {
  cat <<'USAGE'
usage: install.sh [--backend docker|systemd] [--hostname H]
                  [--mode single|multi] [--tag T] [--yes]

Turns a fresh host into a working Pesque (ATProto PDS): installs the
host-side `pesque` CLI plus one backend, then prints the handoff steps.

  --backend   docker (default): the CLI creates and owns one container
              (docker run -d, data in a named volume). systemd: unpack the
              release to /opt and install the pesque.service unit (Linux,
              root).
  --hostname  domain clients will use (pds.example.com). Written into a
              pesque.conf in the current directory (docker) or into
              /etc/pesque/pesque.env (systemd).
  --mode      single (default) or multi.
  --tag       release tag (default: the latest release).
  --yes       non-interactive: take flags and defaults, error when a required
              value is missing (--hostname for --backend systemd).

Every value is also accepted as --flag=value. There is no guided setup and
no bundled proxy: TLS is the operator's responsibility. Secrets are
generated by the release on first boot; this script writes nothing secret.
USAGE
}

log() { printf '==> %s\n' "$*"; }
note() { printf 'note: %s\n' "$*"; }
die() {
  printf 'error: %s\n' "$1" >&2
  exit "${2:-1}"
}

# --- helpers -------------------------------------------------------------------

# sha256 of a file as hex, whatever tool the host has.
sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | cut -d' ' -f1
  elif command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | cut -d' ' -f1
  else
    die "need sha256sum or shasum to verify downloads" 3
  fi
}

# The checksum for $2 in a sha256sum-style listing (entry may carry a path).
sums_entry() {
  sed -n "s/^\\([0-9a-fA-F]\\{64\\}\\)[[:space:]].*$2\$/\\1/p" "$1" | head -n 1
}

# Download one release asset into the work dir and verify it against
# SHA256SUMS before anything else touches it. $2 moves it into place.
fetch_asset() {
  f_asset=$1
  log "downloading $f_asset"
  curl -fsSL --max-time 600 -o "$work/$f_asset" "$base/$tag/$f_asset" ||
    die "download failed: $base/$tag/$f_asset" 3
  f_want="$(sums_entry "$work/SHA256SUMS" "$f_asset")"
  [ -n "$f_want" ] || die "no checksum for $f_asset in SHA256SUMS" 3
  f_got="$(sha256_of "$work/$f_asset")"
  [ "$f_got" = "$f_want" ] ||
    die "checksum mismatch for $f_asset (want $f_want, got $f_got)" 3
  if [ $# -ge 2 ]; then
    mv "$work/$f_asset" "$2"
  fi
}

# Compare two dotted versions: prints -1, 0 or 1. Non-numeric segments count
# as equal (fall through to the caller's sha check instead).
ver_cmp() {
  _a="${1#v}"
  _b="${2#v}"
  while [ -n "$_a" ] || [ -n "$_b" ]; do
    seg_a="${_a%%.*}"
    case "${_a#*.}" in "$_a") _a="" ;; *) _a="${_a#*.}" ;; esac
    seg_b="${_b%%.*}"
    case "${_b#*.}" in "$_b") _b="" ;; *) _b="${_b#*.}" ;; esac
    seg_a="${seg_a:-0}"
    seg_b="${seg_b:-0}"
    case "$seg_a$seg_b" in *[!0-9]*) printf '0\n'; return 0 ;; esac
    if [ "$seg_a" -lt "$seg_b" ]; then
      printf -- '-1\n'
      return 0
    fi
    if [ "$seg_a" -gt "$seg_b" ]; then
      printf '1\n'
      return 0
    fi
  done
  printf '0\n'
}

# The CLI's own version line, or nothing when it cannot tell.
cli_version() {
  "$1" version 2>/dev/null | sed -n 's/^pesque-cli //p' | head -n 1 || true
}

# --- steps ---------------------------------------------------------------------

detect_target() {
  case "$(uname -s)/$(uname -m)" in
    Linux/x86_64) target=x86_64-linux-musl ;;
    Linux/aarch64) target=aarch64-linux-musl ;;
    Darwin/arm64) target=aarch64-macos ;;
    Darwin/x86_64) target=x86_64-macos ;;
    MINGW*/x86_64 | MSYS*/x86_64 | CYGWIN*/x86_64) target=x86_64-windows-gnu ;;
    *)
      die "no prebuilt pesque for $(uname -s)/$(uname -m).
Releases carry: x86_64-linux-musl, aarch64-linux-musl, x86_64-macos,
aarch64-macos, x86_64-windows-gnu. See https://github.com/$repo/releases/latest" 3
      ;;
  esac
  exe_ext=""
  case $target in
    *windows*) exe_ext=.exe ;;
  esac
}

preflight() {
  command -v curl >/dev/null 2>&1 || die "curl is required" 3
  case $backend in
    docker)
      command -v docker >/dev/null 2>&1 ||
        die "docker is required for the docker backend (https://docs.docker.com/engine/install/)" 3
      docker info >/dev/null 2>&1 ||
        die "the docker daemon is not running; start it and run this again" 3
      ;;
    systemd)
      [ "$(uname -s)" = Linux ] ||
        die "the systemd backend is Linux-only; use the docker backend" 3
      [ "$(id -u)" = 0 ] ||
        die "the systemd backend needs root: re-run with sudo or su" 3
      command -v systemctl >/dev/null 2>&1 ||
        die "systemctl not found: is systemd the init?" 3
      command -v tar >/dev/null 2>&1 || die "tar not found" 3
      command -v useradd >/dev/null 2>&1 || die "useradd not found" 3
      ;;
  esac
}

resolve_tag() {
  if [ -n "$tag" ]; then
    return 0
  fi
  log "resolving the latest release"
  tag="$(curl -fsSL --max-time 30 "$api" |
    sed -n 's/.*"tag_name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"
  [ -n "$tag" ] || die "could not resolve the latest release tag from $api; pass --tag T" 3
}

# Where the CLI binary goes: /usr/local/bin when writable, ~/.local/bin when
# not (with a PATH warning), or PESQUE_PREFIX outright.
choose_prefix() {
  if [ -n "${PESQUE_PREFIX:-}" ]; then
    prefix=$PESQUE_PREFIX
    return 0
  fi
  prefix=/usr/local
  if ! mkdir -p "$prefix/bin" 2>/dev/null || [ ! -w "$prefix/bin" ]; then
    prefix=$HOME/.local
  fi
}

install_cli() {
  log "installing the pesque CLI (release $tag, target $target)"
  asset="pesque-$target$exe_ext"
  fetch_asset "$asset"
  chmod 755 "$work/$asset"

  choose_prefix
  mkdir -p "$prefix/bin"
  dest="$prefix/bin/pesque$exe_ext"

  # Idempotence: an identical install is left alone, an older one is replaced,
  # a newer one is kept. Equality is decided by sha256, the older/newer
  # question by the CLI's own version. Same version with different bytes is
  # still replaced: the installed file may be corrupt, and "nothing to do"
  # must never keep bad bytes.
  if [ -e "$dest" ]; then
    want="$(sums_entry "$work/SHA256SUMS" "$asset")"
    got="$(sha256_of "$dest")"
    if [ -n "$want" ] && [ "$got" = "$want" ]; then
      note "$dest already has the $tag build; nothing to do"
      return 0
    fi
    installed_ver="$(cli_version "$dest")"
    target_ver="$(cli_version "$work/$asset")"
    if [ -n "$installed_ver" ] && [ -n "$target_ver" ]; then
      case "$(ver_cmp "$installed_ver" "$target_ver")" in
        1)
          note "$dest is version $installed_ver, newer than the latest release ($target_ver); not downgrading"
          return 0
          ;;
        0)
          note "$dest is version $installed_ver but its bytes differ from the $tag release; replacing it"
          ;;
      esac
    fi
  fi
  mv "$work/$asset" "$dest"
  log "pesque CLI installed at $dest"
  case ":$PATH:" in
    *":$prefix/bin:"*) ;;
    *) note "$prefix/bin is not in your PATH; add it: export PATH=\"$prefix/bin:\$PATH\"" ;;
  esac
}

# Docker's default log driver keeps json-file growth unbounded: one chatty
# container fills the disk and takes the whole host down. Cap every container
# at 500 MiB across 4 files, but only when the host has no daemon.json yet:
# the file replaces the daemon's whole config, so an existing one must win.
configure_docker_logs() {
  [ "$backend" = docker ] || return 0
  [ "$(uname -s)" = Linux ] || return 0
  [ "$(id -u)" = 0 ] || {
    note "not root: skipping docker log rotation"
    return 0
  }
  if [ -f "$sysroot/etc/docker/daemon.json" ]; then
    note "$sysroot/etc/docker/daemon.json exists; leaving it alone"
    return 0
  fi
  mkdir -p "$sysroot/etc/docker"
  cat >"$sysroot/etc/docker/daemon.json" <<'EOF'
{
  "log-driver": "json-file",
  "log-opts": { "max-size": "500m", "max-file": "4" }
}
EOF
  note "capped docker logs at 500m x 4 files per container (prevents the disk-full death)"
  # A failed restart must not abort the install: the unit may be named
  # differently (snap, distro packaging), so fall through to `service` and
  # finally to a note. The `if` guards keep `set -e` from firing on failure.
  if command -v systemctl >/dev/null 2>&1; then
    if systemctl restart docker; then
      return 0
    fi
    note "systemctl restart docker failed; trying 'service docker restart'"
  fi
  if command -v service >/dev/null 2>&1; then
    if service docker restart; then
      return 0
    fi
  fi
  note "could not restart the docker daemon; restart it by hand to apply the log rotation"
}

backend_docker() {
  log "docker backend: the CLI owns the container; this installer starts nothing"
}

backend_systemd() {
  case "$(uname -m)" in
    x86_64) ;;
    *) die "the release tarball is published for x86_64 only; on this machine use the docker backend or the NixOS flake" 3 ;;
  esac

  asset="pesque-server-x86_64-linux.tar.gz"
  fetch_asset "$asset"
  if [ -d "$sysroot/opt/pesque-$tag" ]; then
    note "$sysroot/opt/pesque-$tag already exists; keeping it (remove it by hand to re-unpack)"
  else
    log "unpacking the release to $sysroot/opt/pesque-$tag"
    mkdir -p "$sysroot/opt/pesque-$tag"
    tar -xzf "$work/$asset" -C "$sysroot/opt/pesque-$tag" --strip-components 1
    chmod 755 "$sysroot/opt/pesque-$tag/bin/pesque" \
      "$sysroot/opt/pesque-$tag/bin/pesque.core" 2>/dev/null || true
  fi
  old_target=""
  if [ -L "$sysroot/opt/pesque" ]; then
    old_target="$(readlink "$sysroot/opt/pesque")"
  fi
  ln -snf "pesque-$tag" "$sysroot/opt/pesque"
  if [ -n "$old_target" ] && [ "$old_target" != "pesque-$tag" ]; then
    note "release swapped; 'pesque update' (or systemctl restart pesque) puts it live"
  fi

  # The service user and the data directory. The release generates its secret
  # inside the data dir on first boot; nothing secret comes from here.
  if ! id -u pesque >/dev/null 2>&1; then
    groupadd --system pesque >/dev/null 2>&1 || true
    login_shell=/usr/sbin/nologin
    [ -x "$login_shell" ] || login_shell=/bin/false
    useradd --system --gid pesque --home-dir "$sysroot/var/lib/pesque" --shell "$login_shell" pesque ||
      die "could not create the pesque system user" 3
  fi
  mkdir -p "$sysroot/var/lib/pesque"
  chown pesque:pesque "$sysroot/var/lib/pesque"
  chmod 700 "$sysroot/var/lib/pesque"

  # Non-secret settings. The unit reads them through EnvironmentFile; the
  # Zig CLI's run_once mirrors the same file, so verbs see the same world.
  mkdir -p "$sysroot/etc/pesque"
  envfile="$sysroot/etc/pesque/pesque.env"
  if [ -f "$envfile" ]; then
    note "$envfile exists; leaving it alone"
  else
    {
      printf '# Pesque server settings: PDS_* keys, one per line (see pesque.conf.example).\n'
      [ -n "$hostname_val" ] && printf 'PDS_HOSTNAME=%s\n' "$hostname_val"
      [ -n "$mode" ] && printf 'PDS_MODE=%s\n' "$mode"
      true
    } >"$envfile"
    # 0600 root-owned: the systemd manager (root) and the CLI's root run_once
    # are the only readers; other users have no business with the settings.
    chmod 600 "$envfile"
  fi

  unit="$sysroot/etc/systemd/system/pesque.service"
  mkdir -p "$sysroot/etc/systemd/system"
  cat >"$work/pesque.service" <<EOF
[Unit]
Description=Pesque (ATProto PDS)
Documentation=https://github.com/$repo
Wants=network-online.target
After=network-online.target

[Service]
Type=exec
User=pesque
Group=pesque
WorkingDirectory=$sysroot/var/lib/pesque
Environment=PDS_DATA_DIR=$sysroot/var/lib/pesque
EnvironmentFile=-$sysroot/etc/pesque/pesque.env
ExecStart=$sysroot/opt/pesque/bin/pesque start
ExecStop=$sysroot/opt/pesque/bin/pesque stop
Restart=on-failure
RestartSec=5
TimeoutStopSec=30
LimitNOFILE=65536
NoNewPrivileges=true

[Install]
WantedBy=multi-user.target
EOF
  if [ -f "$unit" ] && cmp -s "$work/pesque.service" "$unit"; then
    note "$unit is already up to date"
  else
    cp "$work/pesque.service" "$unit"
    systemctl daemon-reload
  fi
  systemctl enable pesque

  if [ -z "$hostname_val" ]; then
    # shellcheck disable=SC2016  # $EDITOR is printed literally, on purpose
    printf '
The release is installed and pesque.service is enabled, but not started:
it needs a hostname first.

  $EDITOR %s/etc/pesque/pesque.env   # PDS_HOSTNAME=pds.example.com
  systemctl start pesque

Then:

  pesque doctor
  pesque account create --handle pds.example.com --email you@example.com

The systemd backend ships no TLS proxy; put one in front before clients can
connect (docs/guides/installation.md, "Behind a TLS proxy").
' "$sysroot"
    return 0
  fi

  systemctl start pesque
  port="$(sed -n 's/^PDS_PORT=//p' "$envfile" | head -n 1)"
  port="${port:-4000}"
  log "waiting for the server to become healthy (port $port)"
  healthy=no
  i=0
  while [ "$i" -lt 45 ]; do
    if curl -fsS --max-time 5 "http://localhost:$port/xrpc/_health" >/dev/null 2>&1; then
      healthy=yes
      break
    fi
    i=$((i + 1))
    sleep 2
  done
  [ "$healthy" = yes ] || die "the server did not come up; check 'journalctl -u pesque -n 100'" 1

  handle="$hostname_val"
  [ "$mode" = multi ] && handle="alice.$hostname_val"
  printf '
The service is up and enabled (pesque.service, release %s at %s/opt/pesque).

Next:

  pesque doctor          # federation preflight
  pesque account create --handle %s --email you@example.com

Data lives in /var/lib/pesque; the unit reads settings from
%s/etc/pesque/pesque.env. The systemd backend ships no TLS proxy; put one in
front before clients can connect (docs/guides/installation.md).
' "$tag" "$sysroot" "$handle" "$sysroot"
}

# --- main ------------------------------------------------------------------------

parse_args() {
  while [ $# -gt 0 ]; do
    case $1 in
      --backend)
        [ $# -ge 2 ] || die "--backend needs a value: docker or systemd" 2
        backend=$2
        shift 2
        ;;
      --backend=*)
        backend="${1#*=}"
        shift
        ;;
      --hostname)
        [ $# -ge 2 ] || die "--hostname needs a value" 2
        hostname_val=$2
        shift 2
        ;;
      --hostname=*)
        hostname_val="${1#*=}"
        shift
        ;;
      --mode)
        [ $# -ge 2 ] || die "--mode needs a value: single or multi" 2
        mode=$2
        shift 2
        ;;
      --mode=*)
        mode="${1#*=}"
        shift
        ;;
      --tag)
        [ $# -ge 2 ] || die "--tag needs a value" 2
        tag=$2
        shift 2
        ;;
      --tag=*)
        tag="${1#*=}"
        shift
        ;;
      --yes)
        yes=1
        shift
        ;;
      --help | -h)
        usage
        exit 0
        ;;
      *)
        die "unknown flag: $1 (see --help)" 2
        ;;
    esac
  done
}

main() {
  parse_args "$@"

  case $backend in
    docker | systemd) ;;
    *) die "--backend must be docker or systemd, got '$backend'" 2 ;;
  esac
  case $mode in
    "" | single | multi) ;;
    *) die "--mode must be single or multi, got '$mode'" 2 ;;
  esac
  if [ -n "$tag" ] && printf '%s' "$tag" | grep -q '[^A-Za-z0-9._-]'; then
    die "--tag must look like v1.2.3, got '$tag'" 2
  fi
  if printf '%s' "$hostname_val" | grep -q '[^A-Za-z0-9.-]'; then
    die "--hostname must be a bare domain (letters, digits, dots, hyphens), got '$hostname_val'" 2
  fi

  # The only prompt in the script; skipped when stdin is not a tty (the piped
  # one-liner), so script text is never eaten as input.
  if [ -t 0 ]; then
    if [ -z "$hostname_val" ] && [ "$backend" = systemd ]; then
      printf 'Domain clients will use (pds.example.com): '
      read -r answer || die "could not read the hostname" 2
      if [ -n "$answer" ]; then hostname_val=$answer; fi
    fi
  fi
  if [ "$yes" = 1 ] && [ "$backend" = systemd ] && [ -z "$hostname_val" ]; then
    die "--backend systemd needs --hostname H in non-interactive mode (it is written into the unit's environment)" 2
  fi

  detect_target
  preflight
  resolve_tag
  log "installing pesque $tag for $target (backend: $backend)"

  work="$(mktemp -d)" || die "could not create a temporary directory" 3
  trap 'rm -rf "$work"' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM

  curl -fsSL --max-time 60 -o "$work/SHA256SUMS" "$base/$tag/SHA256SUMS" ||
    die "could not download SHA256SUMS from $base/$tag" 3

  install_cli
  configure_docker_logs

  case $backend in
    docker)
      backend_docker
      # With a hostname, drop a starter conf the CLI picks up (it reads
      # ./pesque.conf when PESQUE_CONFIG is unset). Without one, point at the
      # example and let the operator write it.
      if [ -n "$hostname_val" ]; then
        if [ -e "$PWD/pesque.conf" ]; then
          note "$PWD/pesque.conf exists; leaving it alone"
        else
          {
            printf '# pesque configuration. Every key is in pesque.conf.example.\n'
            printf 'hostname = %s\n' "$hostname_val"
            printf 'mode = %s\n' "${mode:-single}"
          } >"$PWD/pesque.conf"
          log "wrote $PWD/pesque.conf (hostname=$hostname_val)"
        fi
      fi
      printf '\nNext:\n\n'
      if [ -z "$hostname_val" ]; then
        printf '  1. Write a pesque.conf in this directory (start from\n'
        printf '     pesque.conf.example). The hostname clients will use goes there.\n'
      else
        printf '  1. Review pesque.conf (add handle_domain, crawler and the rest).\n'
      fi
      printf '  2. pesque up\n'
      printf '     The CLI owns one container: docker run -d when absent, docker\n'
      printf '     start when it already exists. Image ghcr.io/zeeetech/pesque:latest,\n'
      printf '     data in the pesque-data volume, published on 127.0.0.1:4000:4000.\n'
      printf '  3. pesque account create --handle pds.example.com --email you@example.com\n\n'
      printf 'The container is tuned with PESQUE_CONTAINER, PESQUE_IMAGE, PESQUE_DATA,\n'
      printf 'PESQUE_CONFIG (a pesque.conf mounted read-only at /data/pesque.conf) and\n'
      printf 'PESQUE_PUBLISH (e.g. a tailnet IP for a homelab). The default publish\n'
      printf 'binds the loopback; put your own TLS proxy in front before clients can\n'
      printf 'connect: no proxy or certificate machinery is bundled. Updates are\n'
      printf 'manual: pesque update [tag].\n\n'
      printf '  pesque logs -f         # follow the server logs\n'
      printf '  pesque health          # once it is up\n\n'
      ;;
    systemd)
      backend_systemd
      ;;
  esac
}

main "$@"
